'use client';

import { useEffect, useId, useRef, type ReactNode } from 'react';
import './stacked-dialog-depth.css';

export interface StackedDialogProps {
  open: boolean;
  onClose: () => void;
  title: string;
  children: ReactNode;
  /** True while another dialog is open on top of this one. */
  covered?: boolean;
  className?: string;
}

/**
 * A modal dialog built on the native <dialog>. Open a second one from inside
 * the first and the first steps back (smaller, dimmer) to show the depth.
 * The browser traps focus in the top dialog; Escape closes only the top one,
 * and each close returns focus to the button that opened it.
 */
export function StackedDialog({
  open,
  onClose,
  title,
  children,
  covered = false,
  className = '',
}: StackedDialogProps) {
  const dialog = useRef<HTMLDialogElement>(null);
  const opener = useRef<HTMLElement | null>(null);
  const titleId = useId();

  useEffect(() => {
    const el = dialog.current;
    if (!el) return;
    if (open && !el.open) {
      opener.current = document.activeElement as HTMLElement | null;
      el.showModal();
    } else if (!open && el.open) {
      el.close();
      opener.current?.focus();
    }
  }, [open]);

  return (
    <dialog
      ref={dialog}
      className={`mg-stack ${className}`}
      aria-labelledby={titleId}
      data-covered={covered}
      onCancel={(event) => {
        event.preventDefault();
        onClose();
      }}
    >
      <div className='mg-stack__head'>
        <h2 id={titleId}>{title}</h2>
        <button
          type='button'
          className='mg-stack__close'
          aria-label={`Close ${title}`}
          onClick={onClose}
        >
          <svg width='16' height='16' viewBox='0 0 16 16' aria-hidden='true'>
            <path
              d='M4 4l8 8M12 4l-8 8'
              fill='none'
              stroke='currentColor'
              strokeWidth='1.75'
              strokeLinecap='round'
            />
          </svg>
        </button>
      </div>
      <div className='mg-stack__body'>{children}</div>
    </dialog>
  );
}

.mg-stack {
  width: min(360px, calc(100% - 32px));
  padding: 0;
  border: 1px solid var(--mg-line, #303030);
  border-radius: 14px;
  background: #121212;
  box-shadow: 0 30px 60px -24px rgba(0, 0, 0, 0.55);
  color: var(--mg-text, #ffffff);
  transition:
    transform 280ms cubic-bezier(0.2, 0.8, 0.2, 1),
    filter 280ms ease;
}

.mg-stack[open] {
  animation: mg-stack-in 240ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

/* The dialog underneath steps back. */
.mg-stack[data-covered='true'] {
  filter: brightness(0.82);
  transform: translateY(-14px) scale(0.94);
}

.mg-stack::backdrop {
  background: rgba(0, 0, 0, 0.35);
}

.mg-stack__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 8px 8px 18px;
  border-bottom: 1px solid var(--mg-line, #303030);
}

.mg-stack__head h2 {
  margin: 0;
  font-size: 16px;
}

.mg-stack__close {
  width: 44px;
  height: 44px;
  border: 0;
  border-radius: 8px;
  background: none;
  color: inherit;
  font-size: 22px;
  cursor: pointer;
}

.mg-stack__body {
  display: grid;
  gap: 12px;
  padding: 16px 18px 18px;
  color: #b8b8b8;
}

.mg-stack button:focus-visible {
  outline: 3px solid var(--mg-accent-text, #648aff);
  outline-offset: 2px;
}

@keyframes mg-stack-in {
  from {
    opacity: 0;
    transform: translateY(16px) scale(0.98);
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-stack {
    transition: none;
  }
  .mg-stack[open] {
    animation: none;
  }
}
